_CORE = '"""ANEIRA V3 unified FastAPI application. No rejected legacy application imports."""\nimport os, json, time, secrets, smtplib, threading, uuid\nfrom email.message import EmailMessage\nfrom pathlib import Path\nfrom fastapi import FastAPI,HTTPException,Request,Response,Depends\nfrom fastapi.responses import FileResponse,JSONResponse,RedirectResponse\nfrom fastapi.staticfiles import StaticFiles\nfrom pydantic import BaseModel,Field\nfrom typing import Any\nimport storage, intelligence as intel, membership\nfrom aneira_assessment.engine import QUESTIONS, DOMAINS, validate_answers, visible_questions, longitudinal\nfrom aneira_affirmations.router import router as interactive_affirmations_router\nfrom dashboard.router import router as private_dashboard_router\nfrom aneira_triggered.router import router as trigger_router\nROOT=Path(__file__).parent\napp=FastAPI(title=\'ANEIRA V3 | Abuse & Relationship Trauma Recovery\',docs_url=None,redoc_url=None,openapi_url=None)\napp.include_router(interactive_affirmations_router)\napp.include_router(private_dashboard_router)\napp.include_router(trigger_router)\napp.mount(\'/recovery-studio\',StaticFiles(directory=ROOT/\'recovery_studio\', html=True),name=\'recovery-studio\')\napp.mount(\'/journal-studio\',StaticFiles(directory=ROOT/\'journal_studio\', html=True),name=\'journal-studio\')\napp.mount(\'/static\',StaticFiles(directory=ROOT/\'static\'),name=\'static\')\napp.mount(\'/education\',StaticFiles(directory=ROOT/\'education\', html=True),name=\'education\')\napp.mount(\'/emotions\',StaticFiles(directory=ROOT/\'emotions\', html=True),name=\'emotions\')\napp.mount(\'/assessments\',StaticFiles(directory=ROOT/\'assessments\', html=True),name=\'assessments\')\napp.mount(\'/rcdi\',StaticFiles(directory=ROOT/\'rcdi\', html=True),name=\'rcdi\')\napp.mount(\'/ipsd\',StaticFiles(directory=ROOT/\'ipsd\', html=True),name=\'ipsd\')\napp.mount(\'/integrated-assessment\',StaticFiles(directory=ROOT/\'integrated-assessment\', html=True),name=\'integrated-assessment\')\napp.mount(\'/membership\',StaticFiles(directory=ROOT/\'membership\', html=True),name=\'membership\')\napp.mount(\'/build-your-future\',StaticFiles(directory=ROOT/\'build-your-future\', html=True),name=\'build-your-future\')\napp.mount(\'/organization\',StaticFiles(directory=ROOT/\'organization\', html=True),name=\'organization\')\n@app.on_event(\'startup\')\ndef startup():\n storage.init()\n storage.recover_owner_once()\n membership.init()\n # Preserve the existing account, ID, sessions, and every saved record.\n # Grant the designated platform owner a permanent administrator role.\n with storage.connect() as db:\n  db.execute("UPDATE users SET role=\'admin\', disabled=0 WHERE lower(trim(email))=?",(\'chdarden23@gmail.com\',))\n\n# Fail-closed entitlement gate: access to recovery content is never controlled by a\n# browser setting or a deployment environment flag. Only the public onboarding\n# flows and privacy/data-rights operations are exempt.\nMEMBER_PAGE_PREFIXES = (\n \'/assessments\',\'/education\',\'/emotions\',\'/integrated-assessment\',\n \'/rcdi\',\'/ipsd\',\'/recovery-studio\',\'/journal-studio\',\'/organization\',\'/dashboard\',\n)\nPUBLIC_API_PATHS = frozenset({\n \'/api/register\',\'/api/login\',\'/api/logout\',\'/api/me\',\'/api/forgot-password\',\n \'/api/reset-password\',\'/api/membership/plans\',\'/api/membership/status\',\n \'/api/membership/checkout\',\'/api/membership/trial\',\'/api/membership/checkout-status\',\'/api/membership/portal\',\'/api/membership/redeem\',\n \'/api/billing/stripe/webhook\',\'/api/corporate/inquiry\',\n \'/api/export\',\'/api/account\',\n})\ndef _protected_path(path,method):\n # FastAPI/Starlette static mounts accept both slash and no-slash paths.\n if any(path==prefix or path.startswith(prefix+\'/\') for prefix in MEMBER_PAGE_PREFIXES):\n  return True\n if path.startswith(\'/api/\'):\n  if path in PUBLIC_API_PATHS:return False\n  # Admin endpoints have independent administrator-role authentication.\n  if path.startswith(\'/api/admin/\'):return False\n  # Organization APIs require authenticated owner and verify organization\n  # ownership for every management action; revoked subscriptions cannot issue seats.\n  if path.startswith(\'/api/organization/\'):return False\n  # Allow previous customers to delete their own saved records without paying.\n  if method==\'DELETE\' and path.startswith(\'/api/records/\'):return False\n  return True\n return False\n\n@app.middleware(\'http\')\nasync def protections(request,call_next):\n path=request.url.path\n if os.environ.get(\'ANEIRA_DEMO_MODE\')==\'1\' and request.method in (\'POST\',\'PUT\',\'PATCH\',\'DELETE\') and path not in (\'/api/logout\',\'/api/journal-studio/plan\',\'/api/recovery-studio/affirmations/start\',\'/api/recovery-studio/affirmations/respond\',\'/api/recovery-studio/affirmations/outcome\'):\n  result=JSONResponse({\'detail\':\'Demo mode does not persist sensitive information\'},status_code=403)\n elif _protected_path(path,request.method):\n  profile=storage.identify_profile(request.cookies.get(\'aneira_session\'))\n  if not profile or (profile[\'role\']!=\'admin\' and not membership.access(profile[\'id\'])[\'active\']):\n   if request.method==\'GET\' and not path.startswith(\'/api/\') and \'text/html\' in request.headers.get(\'accept\',\'\'):\n    result=RedirectResponse(\'/membership/\',status_code=303)\n   else:\n    result=JSONResponse({\'detail\':\'Active ANEIRA membership or valid invitation code required\'},status_code=403)\n  else:result=await call_next(request)\n else:result=await call_next(request)\n result.headers[\'Cache-Control\']=\'no-store, max-age=0\'\n result.headers[\'X-Content-Type-Options\']=\'nosniff\'\n result.headers[\'Referrer-Policy\']=\'no-referrer\'\n result.headers[\'X-Frame-Options\']=\'DENY\'\n result.headers[\'Content-Security-Policy\']="default-src \'self\'; img-src \'self\' data:; style-src \'self\' \'unsafe-inline\'; script-src \'self\'; connect-src \'self\'; font-src \'self\'; frame-ancestors \'none\'"\n return result\n@app.get(\'/assessment\')\n@app.get(\'/assessment/\')\n@app.get(\'/abuse-assessment\')\n@app.get(\'/abuse-assessment/\')\n@app.get(\'/assessments-home\')\ndef assessments_legacy_redirect():return RedirectResponse(\'/assessments/\',status_code=307)\n@app.get(\'/\')\ndef home():return FileResponse(ROOT/\'static/index.html\')\n@app.get(\'/release-version\')\ndef release_version():return {\'release\':\'ANEIRA-20261014-TRIAL-STRIPE-INBOX-V2\', \'image\':\'/static/aneira_archway.jpg\'}\n@app.get(\'/admin\')\ndef admin_redirect():return RedirectResponse(\'/admin/\',status_code=307)\n@app.get(\'/admin/\')\ndef admin_page():return FileResponse(ROOT/\'static/admin.html\')\nclass JournalPlan(BaseModel):\n mode:str=\'guided\';emotion:str=\'\';experience:str=\'\';intention:str=\'express\';branch:str=\'\';depth:str=\'gentle\';journal_id:str=\'\'\n@app.post(\'/api/journal-studio/plan\')\ndef journal_plan(p:JournalPlan):\n from journal_studio.decision_engine import recommend_path\n try:return recommend_path(mode=p.mode,emotion=p.emotion,experience=p.experience,intention=p.intention,branch=p.branch,depth=p.depth,journal_id=p.journal_id)\n except ValueError as error:raise HTTPException(422,str(error))\n\n@app.get(\'/health\')\ndef health():return {\'status\':\'ok\',\'version\':\'V3\',\'exercises\':len(intel.EXERCISES),\'journals\':len(intel.JOURNALS),\'chapters\':len(intel.CHAPTERS)}\ndef uid(request:Request):\n u=storage.identify(request.cookies.get(\'aneira_session\'))\n if u is None:raise HTTPException(401,\'Sign in to access your private records\')\n return u\n\ndef admin_uid(request:Request):\n profile=storage.identify_profile(request.cookies.get(\'aneira_session\'))\n if profile is None:raise HTTPException(401,\'Administrator sign-in required\')\n if profile[\'role\']!=\'admin\':raise HTTPException(403,\'Administrator permission required\')\n return profile[\'id\']\n\n# A bounded in-process login throttle for the single-worker deployment.\n_LOGIN_FAILURES={}\n_LOGIN_MUTEX=threading.Lock()\ndef login_attempt_key(request,email):\n return (str(request.client.host if request.client else \'unknown\'),email.lower().strip()[:254])\ndef login_blocked(key):\n now=time.time()\n with _LOGIN_MUTEX:\n  failures=[t for t in _LOGIN_FAILURES.get(key,[]) if t>now-900]\n  _LOGIN_FAILURES[key]=failures\n  if len(_LOGIN_FAILURES)>5000:\n   _LOGIN_FAILURES.clear()\n  return len(failures)>=8\ndef record_login_attempt(key,success):\n with _LOGIN_MUTEX:\n  if success:_LOGIN_FAILURES.pop(key,None)\n  else:_LOGIN_FAILURES.setdefault(key,[]).append(time.time())\n\ndef session_cookie_secure(request):\n return not (os.environ.get(\'ANEIRA_INSECURE_LOCAL\')==\'1\' and request.url.hostname in (\'testserver\',\'localhost\',\'127.0.0.1\'))\n\ndef require_origin(request):\n origin=request.headers.get(\'origin\');host=request.headers.get(\'host\')\n if origin and host and not origin.endswith(\'://\'+host):raise HTTPException(403,\'Invalid request origin\')\n\nclass Auth(BaseModel):email:str;password:str\nclass EmailOnly(BaseModel):email:str\nclass AdminStatus(BaseModel):disabled:bool\nclass AdminDelete(BaseModel):confirm_email:str\nclass Reset(BaseModel):token:str;password:str\nclass AnswerPayload(BaseModel):answers:dict=Field(default_factory=dict);save:bool=False\nclass AnswerStore(AnswerPayload):name:str=\'current\';consent:bool=False\nclass Progress(BaseModel):item_id:str;kind:str;completed:bool=True;helpfulness:int|None=None;note:str|None=None;consent:bool=True\nclass Entry(BaseModel):journal_id:str;entry_id:str;answers:dict=Field(default_factory=dict);consent:bool=False\nclass Cognitive(BaseModel):scenario_id:str;choice_id:str;save:bool=False\nclass Affirmation(BaseModel):affirmation_id:str;selection:str;reflection:str=\'\';save:bool=False\nclass IntegratedSave(BaseModel):\n answers:dict[str,Any];result:dict[str,Any];consent:bool=True\nclass IntegratedDraft(BaseModel):\n answers:dict[str,Any];consent:bool=True\nclass InteractiveSessionSave(BaseModel):\n session_id:str;pathway_id:int;state:dict[str,Any];consent:bool=True\n\ndef require_durable_storage():\n # Fail closed in production: ephemeral Render storage cannot honestly be called "saved".\n if not os.environ.get(\'ANEIRA_DATABASE\') and os.environ.get(\'ANEIRA_INSECURE_LOCAL\') != \'1\':\n  raise HTTPException(503,\'Persistent storage is not configured. Your work has not been saved. Please export it instead.\')\n\ndef verify_integrated_answers(answers,complete=True):\n catalog=json.loads((ROOT/\'integrated-assessment/src/questions.json\').read_text(encoding=\'utf-8\'))\n valid={q[\'question_id\']:q for q in catalog}\n if set(answers)-set(valid):raise HTTPException(422,\'Unknown assessment response\')\n if complete and set(answers)!=set(valid):raise HTTPException(422,\'All 66 responses are required\')\n for qid,value in answers.items():\n  if value is None:\n   if complete:raise HTTPException(422,\'Missing answer\')\n   continue\n  q=valid[qid];codes={x[\'code\'] for x in q[\'answer_options\']}\n  if q[\'response_type\']==\'multiple\':\n   if not isinstance(value,list) or not value or len(value)>len(codes) or len(value)!=len(set(value)) or any(x not in codes for x in value) or (\'A\' in value and len(value)>1):raise HTTPException(422,\'Invalid answer option\')\n  elif not isinstance(value,str) or value not in codes:raise HTTPException(422,\'Invalid answer option\')\n if len(json.dumps(answers))>100000:raise HTTPException(413,\'Assessment payload too large\')\n\n@app.get(\'/api/storage/status\')\ndef storage_status():\n return {\'account_storage_configured\':bool(os.environ.get(\'ANEIRA_DATABASE\')),\'type\':\'encrypted SQLite\',\'note\':\'Production persistence requires a mounted durable disk and ANEIRA_DATABASE pointing to that mount.\'}\n\n@app.post(\'/api/assessments/integrated\')\ndef save_integrated_assessment(p:IntegratedSave,request:Request,user:int=Depends(uid)):\n require_origin(request);require_durable_storage()\n if not p.consent:raise HTTPException(400,\'Choose to save to your private account\')\n verify_integrated_answers(p.answers,True)\n r=p.result\n if r.get(\'completion_status\')!=\'complete\' or type(r.get(\'final_severity_level\')) is not int or not 0<=r[\'final_severity_level\']<=5 or not isinstance(r.get(\'response_objects\'),list) or len(r[\'response_objects\'])!=66:\n  raise HTTPException(422,\'A complete scored assessment is required\')\n if len(json.dumps(r))>800000:raise HTTPException(413,\'Assessment report too large\')\n record_id=\'integrated:\'+uuid.uuid4().hex\n item={\'type\':\'integrated-66\',\'id\':record_id,\'answers\':p.answers,\'result\':r,\'saved_at\':time.time(),\'level\':r[\'final_severity_level\'],\'label\':str(r.get(\'final_severity_label\',\'\'))[:120], \'score\':r.get(\'combined_aggregate_score\')}\n storage.save(user,\'assessment\',record_id,item)\n storage.erase(user,\'assessment_draft\',\'integrated:draft\')\n return {\'saved\':True,\'id\':record_id,\'saved_at\':item[\'saved_at\']}\n\n@app.get(\'/api/assessments/integrated/latest\')\ndef latest_integrated_assessment(user:int=Depends(uid)):\n items=[x for x in storage.list_records(user,\'assessment\') if x[\'key\'].startswith(\'integrated:\') and x[\'data\'].get(\'type\')==\'integrated-66\']\n if not items:raise HTTPException(404,\'No completed assessment saved to this account\')\n return items[0][\'data\']\n\n@app.get(\'/api/assessments/integrated/history\')\ndef integrated_assessment_history(user:int=Depends(uid)):\n items=[x for x in storage.list_records(user,\'assessment\') if x[\'key\'].startswith(\'integrated:\') and x[\'data\'].get(\'type\')==\'integrated-66\']\n return {\'items\':[{\'id\':x[\'key\'],\'saved_at\':x[\'updated\'],\'level\':x[\'data\'].get(\'level\'),\'label\':x[\'data\'].get(\'label\'),\'score\':x[\'data\'].get(\'score\')} for x in items]}\n\n@app.get(\'/api/assessments/integrated/item/{item_id}\')\ndef integrated_assessment_item(item_id:str,user:int=Depends(uid)):\n if not item_id.startswith(\'integrated:\') or len(item_id)>100:raise HTTPException(404,\'Assessment not found\')\n item=storage.load(user,\'assessment\',item_id)\n if not item or item.get(\'type\')!=\'integrated-66\':raise HTTPException(404,\'Assessment not found\')\n return item\n\n@app.put(\'/api/assessments/integrated/draft\')\ndef save_integrated_draft(p:IntegratedDraft,request:Request,user:int=Depends(uid)):\n require_origin(request);require_durable_storage()\n if not p.consent:raise HTTPException(400,\'Consent is required for account saving\')\n verify_integrated_answers(p.answers,False)\n storage.save(user,\'assessment_draft\',\'integrated:draft\',{\'answers\':p.answers,\'saved_at\':time.time()})\n return {\'saved\':True}\n\n@app.get(\'/api/assessments/integrated/draft\')\ndef load_integrated_draft(user:int=Depends(uid)):\n item=storage.load(user,\'assessment_draft\',\'integrated:draft\')\n if item is None:raise HTTPException(404,\'No saved draft\')\n return item\n\n@app.get(\'/api/assessment/history\')\ndef legacy_assessment_history(user:int=Depends(uid)):\n return {\'items\':storage.list_records(user,\'assessment\')}\n\n@app.post(\'/api/interactives/sessions\')\ndef save_emotional_session(p:InteractiveSessionSave,request:Request,user:int=Depends(uid)):\n require_origin(request);require_durable_storage()\n if not p.consent:raise HTTPException(400,\'Choose to save this interactive to your private account\')\n if len(p.session_id)>80 or not p.session_id or any(c not in \'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_\' for c in p.session_id):raise HTTPException(422,\'Invalid session reference\')\n if not 1<=p.pathway_id<=31 or p.state.get(\'id\')!=p.pathway_id or type(p.state.get(\'step\')) is not int or not 0<=p.state[\'step\']<=9:\n  raise HTTPException(422,\'Invalid interactive state\')\n if len(json.dumps(p.state))>80000:raise HTTPException(413,\'Interactive state too large\')\n key=\'emotion:\'+p.session_id\n data={\'session_id\':p.session_id,\'pathway_id\':p.pathway_id,\'state\':p.state,\'saved_at\':time.time(),\'completed\':p.state[\'step\']>=9}\n storage.save(user,\'emotion_session\',key,data)\n return {\'saved\':True,\'session_id\':p.session_id,\'completed\':data[\'completed\']}\n\n@app.get(\'/api/interactives/sessions\')\ndef emotional_sessions(user:int=Depends(uid)):\n return {\'items\':[{\'key\':x[\'key\'],\'id\':x[\'data\'].get(\'session_id\'),\'pathway_id\':x[\'data\'].get(\'pathway_id\'),\'step\':x[\'data\'].get(\'state\',{}).get(\'step\'),\'completed\':x[\'data\'].get(\'completed\'),\'saved_at\':x[\'updated\']} for x in storage.list_records(user,\'emotion_session\')]}\n\n@app.get(\'/api/interactives/sessions/{session_id}\')\ndef emotional_session(session_id:str,user:int=Depends(uid)):\n item=storage.load(user,\'emotion_session\',\'emotion:\'+session_id)\n if item is None:raise HTTPException(404,\'Saved experience not found\')\n return item\n\n\n\nclass CheckoutStart(BaseModel):\n plan_code:str\n organization_name:str|None=None\nclass CodeUse(BaseModel):\n code:str\nclass PhoenixNoteUpdate(BaseModel):\n code_hash:str\n recipient:str=\'\'\n purpose:str=\'\'\n organization:str=\'\'\n notes:str=\'\'\n\nclass CodeIssue(BaseModel):\n recipient:str=\'\'\n purpose:str=\'\'\n organization:str=\'\'\n notes:str=\'\'\n count:int=1\n organization_id:int|None=None\n expires_days:int|None=None\nclass CodeRevoke(BaseModel):\n code_hash:str\n organization_id:int|None=None\n\n@app.get(\'/api/membership/plans\')\ndef membership_plans():\n return {\'plans\':[p for p in membership.plan_public() if p[\'kind\']==\'individual\'],\'payments_configured\':membership.stripe_available(),\'paywall_enabled\':True}\n\n@app.get(\'/api/membership/status\')\ndef membership_status(user:int=Depends(uid)):\n return membership.summary_for_user(user)|{\'paywall_enabled\':True}\n\n@app.post(\'/api/membership/checkout\')\ndef start_membership_checkout(p:CheckoutStart,request:Request,user:int=Depends(uid)):\n require_origin(request)\n if p.plan_code not in (\'individual_monthly\',\'individual_yearly\'):raise HTTPException(422,\'Contact for corporate pricing\')\n profile=storage.identify_profile(request.cookies.get(\'aneira_session\'))\n try:return {\'url\':membership.checkout(user,profile[\'email\'],p.plan_code,p.organization_name)}\n except ValueError as exc:raise HTTPException(422,str(exc))\n except RuntimeError as exc:raise HTTPException(503,str(exc))\n\n@app.get(\'/api/membership/checkout-status\')\ndef membership_checkout_status(session_id:str,user:int=Depends(uid)):\n try:return membership.reconcile_checkout(user,session_id)\n except ValueError as exc:raise HTTPException(400,str(exc))\n except RuntimeError as exc:raise HTTPException(503,str(exc))\n\n@app.post(\'/api/membership/portal\')\ndef membership_billing_portal(request:Request,user:int=Depends(uid)):\n require_origin(request)\n try:return {\'url\':membership.billing_portal(user)}\n except ValueError as exc:raise HTTPException(404,str(exc))\n except RuntimeError as exc:raise HTTPException(503,str(exc))\n\n@app.post(\'/api/membership/redeem\')\ndef membership_redeem(p:CodeUse,request:Request,user:int=Depends(uid)):\n require_origin(request)\n try:result=membership.redeem(user,p.code.strip())\n except ValueError as exc:raise HTTPException(400,str(exc))\n if not result:raise HTTPException(400,\'Invalid or unavailable access code\')\n return result\n\nclass CorporateInquiry(BaseModel):\n organization:str=Field(min_length=2,max_length=120)\n contact_name:str=Field(min_length=2,max_length=100)\n email:str=Field(min_length=5,max_length=254)\n phone:str=Field(default=\'\',max_length=50)\n message:str=Field(min_length=10,max_length=3000)\n website:str=\'\'\nclass InquiryUpdate(BaseModel):status:str\n_INQUIRY_THROTTLE={}\n_INQUIRY_LOCK=threading.Lock()\n\ndef _notify_inquiry(inquiry_id,company,email):\n required=[\'ANEIRA_SMTP_HOST\',\'ANEIRA_SMTP_USER\',\'ANEIRA_SMTP_PASSWORD\',\'ANEIRA_SMTP_FROM\']\n if not all(os.environ.get(k) for k in required):return\n target=os.environ.get(\'ANEIRA_ADMIN_ALERT_EMAIL\') or os.environ.get(\'ANEIRA_SMTP_FROM\')\n if not target:return\n msg=EmailMessage();msg[\'From\']=os.environ[\'ANEIRA_SMTP_FROM\'];msg[\'To\']=target\n msg[\'Subject\']=\'ANEIRA organizational inquiry #\'+str(inquiry_id)\n msg.set_content(\'New organizational pricing inquiry\\nOrganization: \'+company+\'\\nReply email: \'+email+\'\\nReview securely in the ANEIRA administrator inbox: \'+os.environ.get(\'ANEIRA_PUBLIC_URL\',\'\').rstrip(\'/\')+\'/admin/\')\n try:\n  with smtplib.SMTP_SSL(os.environ[\'ANEIRA_SMTP_HOST\'],int(os.environ.get(\'ANEIRA_SMTP_PORT\',\'465\')),timeout=8) as smtp:\n   smtp.login(os.environ[\'ANEIRA_SMTP_USER\'],os.environ[\'ANEIRA_SMTP_PASSWORD\']);smtp.send_message(msg)\n except Exception:pass  # Inquiry remains saved and visible in administrator inbox.\n\n@app.post(\'/api/membership/trial\')\ndef membership_trial(request:Request,user:int=Depends(uid)):\n require_origin(request)\n profile=storage.identify_profile(request.cookies.get(\'aneira_session\'))\n try:return membership.start_trial(user)\n except ValueError as e:raise HTTPException(409,str(e))\n except RuntimeError as e:raise HTTPException(503,str(e))\n\n@app.get(\'/api/membership/trial\')\ndef membership_trial_status(user:int=Depends(uid)):\n if storage.is_admin(user):\n  return {\'used\':False,\'active\':False,\'expires_at\':None,\'administrator_exempt\':True}\n return membership.trial_status(user)\n\n@app.post(\'/api/corporate/inquiry\')\ndef corporate_inquiry(p:CorporateInquiry,request:Request):\n require_origin(request)\n if p.website:return {\'received\':True}\n if \'@\' not in p.email or \'.\' not in p.email.rsplit(\'@\',1)[-1]:raise HTTPException(422,\'Enter a valid email address\')\n address=request.client.host if request.client else \'unknown\'\n now=time.time()\n with _INQUIRY_LOCK:\n  recent=[t for t in _INQUIRY_THROTTLE.get(address,[]) if now-t<3600]\n  if len(recent)>=5:raise HTTPException(429,\'Too many inquiries. Please try again later.\')\n  recent.append(now);_INQUIRY_THROTTLE[address]=recent\n  if len(_INQUIRY_THROTTLE)>5000:_INQUIRY_THROTTLE.clear()\n inquiry_id=membership.create_inquiry(p.organization.strip(),p.contact_name.strip(),p.email.strip(),p.phone.strip(),p.message.strip())\n threading.Thread(target=_notify_inquiry,args=(inquiry_id,p.organization.strip(),p.email.strip()),daemon=True).start()\n return {\'received\':True,\'message\':\'Your inquiry has been received. Our team will contact you.\'}\n\n@app.get(\'/api/admin/inquiries\')\ndef admin_inquiries(status:str=\'\',user:int=Depends(admin_uid)):\n if status and status not in (\'new\',\'contacted\',\'in_progress\',\'closed\'):raise HTTPException(422,\'Invalid status\')\n return {\'items\':membership.list_inquiries(status),\'unread\':membership.inquiry_count()}\n\n@app.post(\'/api/admin/inquiries/{inquiry_id}/status\')\ndef admin_inquiry_status(inquiry_id:int,p:InquiryUpdate,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n try:ok=membership.update_inquiry(inquiry_id,p.status)\n except ValueError as e:raise HTTPException(422,str(e))\n if not ok:raise HTTPException(404,\'Inquiry not found\')\n return {\'updated\':True,\'unread\':membership.inquiry_count()}\n\n@app.get(\'/api/organization/list\')\ndef organization_list(user:int=Depends(uid)):\n return {\'organizations\':membership.owned_organizations(user)}\n\n@app.get(\'/api/organization/{organization_id}/overview\')\ndef organization_overview(organization_id:int,user:int=Depends(uid)):\n data=membership.org_overview(user,organization_id)\n if data is None:raise HTTPException(404,\'Organization not found\')\n return data\n\n@app.post(\'/api/organization/{organization_id}/codes\')\ndef organization_codes(organization_id:int,p:CodeIssue,request:Request,user:int=Depends(uid)):\n require_origin(request)\n try:return {\'codes\':membership.issue_codes(user,\'organization\',p.count,organization_id,p.expires_days)}\n except PermissionError as exc:raise HTTPException(403,str(exc))\n except ValueError as exc:raise HTTPException(400,str(exc))\n\n@app.post(\'/api/organization/{organization_id}/codes/revoke\')\ndef organization_revoke(organization_id:int,p:CodeRevoke,request:Request,user:int=Depends(uid)):\n require_origin(request)\n try:return membership.revoke(user,p.code_hash,organization_id)\n except PermissionError as exc:raise HTTPException(403,str(exc))\n except ValueError as exc:raise HTTPException(400,str(exc))\n\n@app.get(\'/api/admin/membership-overview\')\ndef admin_membership_overview(user:int=Depends(admin_uid)):\n return membership.platform_membership_overview()\n\n@app.get(\'/api/admin/phoenix\')\ndef admin_phoenix(user:int=Depends(admin_uid)):\n return membership.codes_for_platform()\n\n@app.post(\'/api/admin/phoenix/codes\')\ndef create_phoenix(p:CodeIssue,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n try:return {\'codes\':membership.issue_codes(user,\'phoenix\',p.count,expires_days=p.expires_days,recipient=p.recipient,purpose=p.purpose,recipient_organization=p.organization,notes=p.notes)}\n except ValueError as exc:raise HTTPException(400,str(exc))\n\n@app.post(\'/api/admin/phoenix/notes\')\ndef save_phoenix_notes(p:PhoenixNoteUpdate,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n try:return membership.update_phoenix_notes(user,p.code_hash,p.recipient,p.purpose,p.organization,p.notes)\n except ValueError as exc:raise HTTPException(400,str(exc))\n\n@app.post(\'/api/admin/phoenix/revoke\')\ndef revoke_phoenix(p:CodeRevoke,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n try:return membership.revoke(user,p.code_hash)\n except ValueError as exc:raise HTTPException(400,str(exc))\n\n@app.post(\'/api/billing/stripe/webhook\')\nasync def stripe_webhook(request:Request):\n raw=await request.body()\n if len(raw)>1000000:raise HTTPException(413,\'Webhook payload too large\')\n try:\n  event=membership.verified_event(raw,request.headers.get(\'stripe-signature\',\'\'))\n  membership.apply_stripe_event(event)\n except (ValueError,KeyError,TypeError) as exc:raise HTTPException(400,\'Webhook could not be verified or processed\') from exc\n return {\'received\':True}\n\n\n# Google OAuth sign-in, mapped only to existing ANEIRA accounts.\n# Requires GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET configured in Render.\n@app.get(\'/auth/google\')\ndef google_start(request:Request):\n from urllib.parse import urlencode\n client_id=os.environ.get(\'GOOGLE_CLIENT_ID\',\'\').strip()\n client_secret=os.environ.get(\'GOOGLE_CLIENT_SECRET\',\'\').strip()\n if not client_id or not client_secret:\n  raise HTTPException(503,\'Google sign-in is not configured for this deployment\')\n state=secrets.token_urlsafe(32)\n callback=os.environ.get(\'ANEIRA_GOOGLE_REDIRECT_URI\',\'https://aneiraapp.com/auth/google/callback\')\n params={\'client_id\':client_id,\'redirect_uri\':callback,\'response_type\':\'code\',\'scope\':\'openid email profile\',\'state\':state,\'prompt\':\'select_account\'}\n response=RedirectResponse(\'https://accounts.google.com/o/oauth2/v2/auth?\'+urlencode(params),status_code=302)\n response.set_cookie(\'aneira_google_state\',state,httponly=True,secure=session_cookie_secure(request),samesite=\'lax\',max_age=600,path=\'/auth/google\')\n return response\n\n@app.get(\'/auth/google/callback\')\ndef google_callback(request:Request,code:str=\'\',state:str=\'\',error:str=\'\'):\n from urllib.parse import urlencode\n from urllib.request import Request as URLRequest, urlopen\n import hmac\n supplied=request.cookies.get(\'aneira_google_state\',\'\')\n if error:raise HTTPException(401,\'Google sign-in was cancelled or denied\')\n if not code or not state or not supplied or not hmac.compare_digest(state,supplied):\n  raise HTTPException(403,\'Invalid Google sign-in state\')\n client_id=os.environ.get(\'GOOGLE_CLIENT_ID\',\'\').strip()\n client_secret=os.environ.get(\'GOOGLE_CLIENT_SECRET\',\'\').strip()\n if not client_id or not client_secret:raise HTTPException(503,\'Google sign-in is not configured\')\n callback=os.environ.get(\'ANEIRA_GOOGLE_REDIRECT_URI\',\'https://aneiraapp.com/auth/google/callback\')\n form=urlencode({\'code\':code,\'client_id\':client_id,\'client_secret\':client_secret,\'redirect_uri\':callback,\'grant_type\':\'authorization_code\'}).encode()\n try:\n  with urlopen(URLRequest(\'https://oauth2.googleapis.com/token\',data=form,headers={\'Content-Type\':\'application/x-www-form-urlencoded\'}),timeout=12) as conn:\n   payload=json.load(conn)\n  access_token=payload[\'access_token\']\n  with urlopen(URLRequest(\'https://openidconnect.googleapis.com/v1/userinfo\',headers={\'Authorization\':\'Bearer \'+access_token}),timeout=12) as conn:\n   identity=json.load(conn)\n except Exception as exc:\n  raise HTTPException(401,\'Google authentication could not be completed\') from exc\n if identity.get(\'email_verified\') is not True or not identity.get(\'email\') or not identity.get(\'sub\'):\n  raise HTTPException(403,\'A verified Google email is required\')\n email=identity[\'email\'].strip().lower()\n # Preserve existing users and their password hashes. Never fabricate new accounts.\n with storage.connect() as db:\n  account=db.execute(\'SELECT id,disabled FROM users WHERE lower(trim(email))=?\',(email,)).fetchone()\n if not account or account[\'disabled\']:\n  raise HTTPException(403,\'No active ANEIRA account matches this Google email. Sign in with your existing account first.\')\n token=secrets.token_urlsafe(40)\n with storage.connect() as db:\n  db.execute(\'INSERT INTO sessions(token_hash,user_id,expires) VALUES(?,?,?)\',(storage.digest(token),account[\'id\'],time.time()+storage.SESSION_AGE))\n response=RedirectResponse(\'/admin/\' if storage.is_admin(account[\'id\']) else \'/dashboard/\',status_code=303)\n response.delete_cookie(\'aneira_google_state\',path=\'/auth/google\')\n response.set_cookie(\'aneira_session\',token,httponly=True,secure=session_cookie_secure(request),samesite=\'lax\',max_age=storage.SESSION_AGE,path=\'/\')\n return response\n\n@app.post(\'/api/register\')\ndef register(p:Auth,request:Request,response:Response):\n require_origin(request)\n if not 3<=len(p.email)<=254 or \'@\' not in p.email:raise HTTPException(422,\'Enter a valid email\')\n try:storage.register(p.email,p.password);token=storage.login(p.email,p.password)\n except ValueError as ex:raise HTTPException(400,str(ex))\n response.set_cookie(\'aneira_session\',token,httponly=True,secure=session_cookie_secure(request),samesite=\'strict\',max_age=storage.SESSION_AGE,path=\'/\')\n return {\'authenticated\':True,\'administrator\':False,\'membership_active\':membership.access(storage.identify(token))[\'active\']}\n@app.post(\'/api/login\')\ndef login(p:Auth,request:Request,response:Response):\n require_origin(request)\n key=login_attempt_key(request,p.email)\n if login_blocked(key):raise HTTPException(429,\'Too many sign-in attempts. Please try again later.\')\n try:token=storage.login(p.email,p.password)\n except ValueError:\n  record_login_attempt(key,False)\n  raise HTTPException(401,\'Incorrect email or password\')\n record_login_attempt(key,True)\n profile=storage.identify_profile(token)\n response.set_cookie(\'aneira_session\',token,httponly=True,secure=session_cookie_secure(request),samesite=\'strict\',max_age=storage.SESSION_AGE,path=\'/\')\n return {\'authenticated\':True,\'administrator\':profile[\'role\']==\'admin\',\'membership_active\':membership.access(profile[\'id\'])[\'active\']}\n@app.post(\'/api/logout\')\ndef logout(request:Request,response:Response):\n require_origin(request);storage.logout(request.cookies.get(\'aneira_session\'));response.delete_cookie(\'aneira_session\',path=\'/\');return {\'authenticated\':False}\n@app.get(\'/api/me\')\ndef me(request:Request,user:int=Depends(uid)):\n profile=storage.identify_profile(request.cookies.get(\'aneira_session\'))\n return {\'authenticated\':True,\'user_id\':user,\'email\':profile[\'email\'],\'administrator\':profile[\'role\']==\'admin\',\'membership_active\':membership.access(user)[\'active\'],\'organization_admin\':bool(membership.owned_organizations(user))}\n@app.post(\'/api/forgot-password\')\ndef forgot(p:EmailOnly,request:Request):\n require_origin(request)\n token=storage.begin_reset(p.email)\n if token and all(os.environ.get(k) for k in [\'ANEIRA_SMTP_HOST\',\'ANEIRA_SMTP_USER\',\'ANEIRA_SMTP_PASSWORD\',\'ANEIRA_PUBLIC_URL\',\'ANEIRA_SMTP_FROM\']):\n  m=EmailMessage();m[\'From\']=os.environ[\'ANEIRA_SMTP_FROM\'];m[\'To\']=p.email;m[\'Subject\']=\'ANEIRA password reset\';m.set_content(\'Reset your password (expires in 15 minutes): \'+os.environ[\'ANEIRA_PUBLIC_URL\'].rstrip(\'/\')+\'/?reset=\'+token)\n  try:\n   with smtplib.SMTP_SSL(os.environ[\'ANEIRA_SMTP_HOST\'],int(os.environ.get(\'ANEIRA_SMTP_PORT\',\'465\')),timeout=10) as s:s.login(os.environ[\'ANEIRA_SMTP_USER\'],os.environ[\'ANEIRA_SMTP_PASSWORD\']);s.send_message(m)\n  except Exception:pass\n return {\'message\':\'If this address is registered and mail is configured, a reset link will arrive shortly.\'}\n@app.post(\'/api/reset-password\')\ndef reset(p:Reset,request:Request):\n require_origin(request)\n try:storage.complete_reset(p.token,p.password)\n except ValueError as e:raise HTTPException(400,str(e))\n return {\'password_reset\':True}\n@app.get(\'/api/admin/summary\')\ndef admin_summary(user:int=Depends(admin_uid)):\n return storage.admin_summary()\n\n@app.get(\'/api/admin/users\')\ndef admin_users(limit:int=50,offset:int=0,user:int=Depends(admin_uid)):\n if limit<1 or limit>100 or offset<0:raise HTTPException(422,\'Invalid pagination\')\n return {\'items\':storage.admin_search_users(\'\',limit,offset),\'limit\':limit,\'offset\':offset}\n\n@app.get(\'/api/admin/accounts\')\ndef admin_accounts(search:str=\'\',limit:int=50,offset:int=0,user:int=Depends(admin_uid)):\n if not 1<=limit<=100 or offset<0:raise HTTPException(422,\'Invalid pagination\')\n return {\'items\':storage.admin_search_users(search,limit,offset),\'limit\':limit,\'offset\':offset}\n\n@app.post(\'/api/admin/accounts/{target_id}/reset-password\')\ndef admin_account_password(target_id:int,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n try:temporary=storage.admin_reset_password(user,target_id)\n except ValueError as err:raise HTTPException(400,str(err))\n return {\'temporary_password\':temporary,\'message\':\'Copy this temporary password now. It is not stored in plaintext.\'}\n\n@app.post(\'/api/admin/accounts/{target_id}/delete-unpaid\')\ndef admin_account_delete(target_id:int,p:AdminDelete,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n with storage.connect() as db:\n  account=db.execute(\'SELECT email FROM users WHERE id=?\',(target_id,)).fetchone()\n if not account:raise HTTPException(404,\'Account not found\')\n if account[\'email\'].lower()!=p.confirm_email.strip().lower():raise HTTPException(422,\'Email confirmation does not match\')\n try:storage.admin_delete_unpaid(user,target_id)\n except ValueError as err:raise HTTPException(409,str(err))\n return {\'deleted\':True,\'email\':account[\'email\']}\n\n@app.post(\'/api/admin/users/{target_id}/status\')\ndef admin_update_user(target_id:int,status:AdminStatus,request:Request,user:int=Depends(admin_uid)):\n require_origin(request)\n try:storage.admin_set_disabled(user,target_id,status.disabled)\n except ValueError as err:raise HTTPException(400,str(err))\n return {\'updated\':True,\'user_id\':target_id,\'disabled\':status.disabled}\n\n@app.get(\'/api/exercises\')\ndef exercises():return {\'items\':intel.EXERCISES}\n@app.get(\'/api/journals\')\ndef journals():return {\'items\':intel.JOURNALS}\n@app.get(\'/api/scenarios\')\ndef scenarios():return {\'items\':intel.SCENARIOS}\n@app.get(\'/api/affirmations/library\')\ndef affirmation_library():\n return {\'items\':[{\'id\':\'AFF-\'+domain.upper(),\'domain\':domain,\'text\':value[0],\'context\':value[1]} for domain,value in intel.AFFIRMATIONS.items()]}\n@app.get(\'/api/affirmation/follow-ups\')\ndef affirm_followups():return {\'choices\':list(intel.FOLLOWUPS)}\n\ndef analysis_for(user,answers):\n previous=[x for x in storage.list_records(user,\'assessment\') if x[\'key\'].startswith(\'assessment-\')];earlier=previous[0][\'data\'][\'answers\'] if previous else None\n activity=storage.list_records(user,\'activity\');completed=[r[\'data\'][\'item_id\'] for r in activity if r[\'data\'].get(\'completed\')]\n feedback={r[\'data\'][\'item_id\']:r[\'data\'].get(\'helpfulness\') for r in activity if r[\'data\'].get(\'helpfulness\') is not None}\n return intel.results(answers,earlier,completed,feedback)\n@app.post(\'/api/activities/progress\')\ndef activity_progress(p:Progress,request:Request,user:int=Depends(uid)):\n require_origin(request)\n if not p.consent:raise HTTPException(400,\'Saving requires consent\')\n if p.kind not in [\'exercise\',\'journal\']:raise HTTPException(422,\'Invalid kind\')\n catalog=intel.EXERCISES if p.kind==\'exercise\' else intel.JOURNALS;idkey=\'exercise_id\' if p.kind==\'exercise\' else \'journal_id\'\n if p.item_id not in {x[idkey] for x in catalog}:raise HTTPException(422,\'Unknown V3 catalog ID\')\n if p.helpfulness is not None and not 0<=p.helpfulness<=5:raise HTTPException(422,\'Invalid helpfulness\')\n storage.save(user,\'activity\',p.kind+\':\'+p.item_id,p.model_dump())\n return {\'saved\':True,\'id\':p.item_id}\n@app.get(\'/api/activities/progress\')\ndef activities_progress(user:int=Depends(uid)):return {\'items\':storage.list_records(user,\'activity\')}\n@app.post(\'/api/journals/entries\')\ndef journal_entry(p:Entry,request:Request,user:int=Depends(uid)):\n require_origin(request)\n if not p.consent:raise HTTPException(400,\'Saving requires consent\')\n if p.journal_id not in {x[\'journal_id\'] for x in intel.JOURNALS}:raise HTTPException(422,\'Unknown V3 journal ID\')\n if not 1<=len(p.entry_id)<=100 or len(json.dumps(p.answers))>200000:raise HTTPException(422,\'Invalid entry\')\n storage.save(user,\'journal_entry\',p.entry_id,{\'journal_id\':p.journal_id,\'answers\':p.answers,\'updated_at\':time.time()});return {\'saved\':True,\'id\':p.entry_id}\n@app.get(\'/api/journals/entries\')\ndef journal_entries(user:int=Depends(uid)):return {\'items\':storage.list_records(user,\'journal_entry\')}\n@app.post(\'/api/cognitive/respond\')\ndef cognitive(p:Cognitive,request:Request,user:int=Depends(uid)):\n require_origin(request);history=[r[\'data\'] for r in storage.list_records(user,\'cognitive\')]\n try:out=intel.cognitive_reply(p.scenario_id,p.choice_id,history)\n except ValueError as ex:raise HTTPException(422,str(ex))\n if p.save:storage.save(user,\'cognitive\',str(int(time.time()*1000000)),{\'scenario_id\':p.scenario_id,\'choice_id\':p.choice_id,\'timestamp\':time.time()})\n return out\n@app.get(\'/api/cognitive/history\')\ndef cognitive_history(user:int=Depends(uid)):return {\'items\':storage.list_records(user,\'cognitive\')}\n@app.post(\'/api/affirmation/respond\')\ndef affirmation(p:Affirmation,request:Request,user:int=Depends(uid)):\n require_origin(request)\n if p.selection not in intel.FOLLOWUPS:raise HTTPException(422,\'Invalid selection\')\n if p.affirmation_id not in {\'AFF-\'+d.upper() for d in intel.AFFIRMATIONS}|{\'AFF-CHOICE\'}:raise HTTPException(422,\'Unknown affirmation\')\n if p.save:storage.save(user,\'affirmation\',str(int(time.time()*1000000)),{\'affirmation_id\':p.affirmation_id,\'selection\':p.selection,\'reflection\':p.reflection,\'timestamp\':time.time()})\n return {\'follow_up\':intel.FOLLOWUPS[p.selection],\'saved\':p.save}\n@app.get(\'/api/progress\')\ndef progress(user:int=Depends(uid)):\n records=storage.list_records(user);return {\'assessment_drafts\':[r for r in records if r[\'kind\']==\'assessment_draft\'],\'emotion_sessions\':[r for r in records if r[\'kind\']==\'emotion_session\'],\'assessments\':[r for r in records if r[\'kind\']==\'assessment\'],\'completed_activities\':[r for r in records if r[\'kind\']==\'activity\'],\'journals\':[r for r in records if r[\'kind\']==\'journal_entry\'],\'affirmations\':[r for r in records if r[\'kind\']==\'affirmation\'],\'cognitive\':[r for r in records if r[\'kind\']==\'cognitive\']}\n@app.get(\'/api/export\')\ndef export(user:int=Depends(uid)):return {\'exported_at\':time.time(),\'records\':storage.list_records(user)}\n@app.delete(\'/api/records/{kind}/{key}\')\ndef delete_record(kind:str,key:str,request:Request,user:int=Depends(uid)):\n require_origin(request)\n if kind not in (\'assessment\',\'assessment_draft\',\'emotion_session\',\'activity\',\'journal_entry\',\'affirmation\',\'cognitive\',\'interactive_affirmation\',\'affirmation_bookmark\'):raise HTTPException(422,\'Invalid kind\')\n storage.erase(user,kind,key);return {\'deleted\':True}\n@app.delete(\'/api/account\')\ndef delete_account(request:Request,user:int=Depends(uid)):\n require_origin(request);storage.delete_user(user);return {\'deleted\':True}\n\n\n'

def _start_aneira():
    root=pathlib.Path(tempfile.mkdtemp(prefix='aneira_membership_'))
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(_PAYLOAD))) as archive:
        archive.extractall(root)
    (root/'main.py').write_text(_CORE,encoding='utf-8')
    sys.path.insert(0,str(root))
    spec=importlib.util.spec_from_file_location('aneira_app_membership',root/'main.py')
    mod=importlib.util.module_from_spec(spec)
    sys.modules[spec.name]=mod
    spec.loader.exec_module(mod)
    return mod.app
app=_start_aneira()


# Canonical web-domain redirect. Keep the verified ANEIRA application above intact.
# Redirect browser navigation from links previously shared on Render to the
# equivalent page on the official domain, preserving paths and query strings.
# Non-GET methods are left alone (particularly Stripe webhook POST requests).
from fastapi import Request as _AneiraRedirectRequest
from fastapi.responses import RedirectResponse as _AneiraRedirectResponse

@app.middleware("http")
async def _aneira_canonical_domain(request: _AneiraRedirectRequest, call_next):
    hostname = (request.headers.get("host") or "").split(":", 1)[0].lower().rstrip(".")
    if hostname == "amiera-qzt4.onrender.com" and request.method in ("GET", "HEAD"):
        path = request.scope.get("raw_path", b"").decode("ascii", errors="replace") or request.url.path
        query = request.scope.get("query_string", b"")
        suffix = ("?" + query.decode("ascii", errors="replace")) if query else ""
        return _AneiraRedirectResponse("https://aneiraapp.com" + path + suffix, status_code=308)
    return await call_next(request)
